import { Component } from '@angular/core';
import { Router } from '@angular/router';
import * as moment from 'moment';
import { MemberService } from 'src/app/services/member.service';

@Component({
  selector: 'app-member-search-form',
  templateUrl: './member-search-form.component.html',
  styleUrls: ['./member-search-form.component.css'],
})
export class MemberSearchFormComponent {
  member = this.getResetObject();

  constructor(private memberService: MemberService, private router: Router) {}

// searchMember(): void {
//     const data = {
//       policyNumber: this.member.policyNumber,
//       memberCardNumber: this.member.memberCardNumber,
//     };

//     // this.memberService.search(data).subscribe({
//     //   next: (res) => {
//     //     console.log(res);
//     //     this.router.navigate(['/results']);
//     //   },
//     //   error: (e) => console.error(e),
//     // });
//     this.memberService.search(data).then((res) => {
//       console.log(res);
//       this.router.navigate(['/results']);
//     });
//   }
async searchMember() {
  const data = {
    policyNumber: this.member.policyNumber,
    memberCardNumber: this.member.memberCardNumber,
  };

  // this.memberService.search(data).subscribe({
  //   next: (res) => {
  //     console.log(res);
  //     this.router.navigate(['/results']);
  //   },
  //   error: (e) => console.error(e),
  // });

  await this.memberService.search(data)
  await this.router.navigate(['/results']);
}
  resetForm(): void {
    this.member = this.getResetObject();
  }

  private getResetObject() {
    return {
      date: moment().format('YYYY-MM-DD'),
      policyNumber: '',
      memberCardNumber: '',
    };
  }
}
<div class="submit-form">
  <h2>Member Search</h2>
  <form #contactForm="ngForm" novalidate>
    <div>
      <div>
        <h5>Service Date</h5>
        <div class="form-group">
          <input
            type="date"
            class="form-control"
            id="date"
            [(ngModel)]="member.date"
            name="date"
          />
        </div>
      </div>
      <div>
        <h5>Search Using</h5>
        <div class="form-group">
          <label class="form-label" for="policyNumber">Policy Number *</label>
          <input
            type="text"
            class="form-control"
            id="policyNumber"
            required
            [(ngModel)]="member.policyNumber"
            name="policyNumber"
          />
        </div>
        <div class="form-group">
          <label class="form-label" for="memberCardNumber"
            >Member Card Number *</label
          >
          <input
            class="form-control"
            id="memberCardNumber"
            required
            [(ngModel)]="member.memberCardNumber"
            name="memberCardNumber"
          />
        </div>
      </div>
      <div class="actions">
        <button
          (click)="searchMember()"
          class="btn btn-primary"
          [disabled]="!contactForm.valid"
        >
          Search
        </button>
        <button
          (click)="resetForm()"
          class="btn btn-secondary"
          [disabled]="!contactForm.valid"
        >
          Reset
        </button>
      </div>
    </div>
  </form>
</div>
